import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    static abstract class Account {
        protected long balance;
        Account(long balance) { this.balance = balance; }

        public final void withdraw(long cents) {
            long total = cents + fee(cents);
            if (balance - total < -overdraftLimit()) throw new IllegalStateException("insufficient funds");
            balance -= total;
        }
        protected abstract long fee(long cents);
        protected long overdraftLimit() { return 0; }
        long balance() { return balance; }
    }

    static final class Checking extends Account {
        Checking(long balance) { super(balance); }
        @Override protected long fee(long cents) { throw new UnsupportedOperationException("TODO: no fee"); }
        // TODO: an overdraft limit of 10000 cents
    }

    static final class Savings extends Account {
        Savings(long balance) { super(balance); }
        @Override protected long fee(long cents) { throw new UnsupportedOperationException("TODO: 1%, at least 50 cents"); }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("savings pays the minimum fee", () -> {
            Account a = new Savings(10_000);
            a.withdraw(1000);
            eq(a.balance(), 8950L);
        });
        test("savings pays 1% on large withdrawals", () -> {
            Account a = new Savings(100_000);
            a.withdraw(20_000);
            eq(a.balance(), 79_800L);
        });
        test("savings never goes negative", () -> {
            Account a = new Savings(1000);
            raises(IllegalStateException.class, () -> a.withdraw(1000));
            eq(a.balance(), 1000L);
        });
        test("checking may overdraw up to 100.00 for free", () -> {
            Account a = new Checking(0);
            a.withdraw(10_000);
            eq(a.balance(), -10_000L);
        });
        test("checking refuses one cent past the limit (boundary)", () -> {
            Account a = new Checking(0);
            raises(IllegalStateException.class, () -> a.withdraw(10_001));
            eq(a.balance(), 0L);
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

